14	/**
15	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
16	 * so tests can assert side-effects by reading that file — the second test-assertion channel
17	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
18	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
19	 *
20	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
21	 * SYNC) so a test reads the record immediately.
22	 */
23	@Service
24	public class Audit {
25	
26	    private final Path file;
27	
28	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
29	        this.file = Path.of(path);
30	    }
31	
32	    /** Append one audit record. Tests assert the exact line(s) in the file. */
33	    public synchronized void record(String entry) {
34	        try {
35	            Path parent = file.toAbsolutePath().getParent();
36	            if (parent != null) {
37	                Files.createDirectories(parent);
38	            }
39	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
40	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
41	        } catch (IOException e) {
42	            throw new UncheckedIOException(e);
43	        }
44	    }
45	
46	    /**
47	     * Append one audit record once the current transaction commits, so a change that is refused or
48	     * rolled back writes nothing. Outside a transaction the record is appended at once.
49	     */
50	    public void recordOnCommit(String entry) {
51	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
52	            record(entry);
53	            return;
54	        }
55	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
56	            @Override
57	            public void afterCommit() {
58	                record(entry);
59	            }
60	        });
61	    }
62	
63	    /** Truncate the audit file. */
64	    public synchronized void clear() {
65	        try {
66	            Files.deleteIfExists(file);
67	        } catch (IOException e) {
68	            throw new UncheckedIOException(e);
69	        }
70	    }
71	}
