145	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
146	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
147	        claim.set(amount, dateOr(sheetId, date), noteOf(note));
