154	     *  by the user who opened the claim. */
155	    @Transactional
156	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
157	        Claim claim = claims.findForUpdate(id, sheetId)
158	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
159	        if (!claim.getStatus().canBecome(next)) {
160	            throw new ResponseStatusException(HttpStatus.CONFLICT,
161	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
162	        }
163	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
164	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
165	                    "The user who opened a claim cannot settle it.");
166	        }
167	        Person person = person(sheetId, claim.getPersonId());
168	        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheets.nextClaimNumber(sheetId)) : claim.getNumber();
169	        claim.setStatus(next);
