271	    /** Change a person's name and grade, refused when someone has saved the person since the editor
272	     *  loaded this version of them. */
273	    @Transactional
274	    public Person update(String sheetId, String user, long id, long version, String name, Grade grade) {
275	        Person person = people.findByIdAndSheetId(id, sheetId)
276	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
277	        if (person.getVersion() != version) {
278	            throw changedMeanwhile();
279	        }
280	        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.keyOf(name), id)) {
281	            throw nameInUse();
