391	
392	@Service
393	public class SheetService {
394	
395	    private final SheetRepository sheets;
396	
397	    public SheetService(SheetRepository sheets) {
398	        this.sheets = sheets;
399	    }
400	
401	    /** The sheet with this id, as the store holds it now; a sheet never loaded before starts empty. */
402	    @Transactional
403	    public Sheet load(String id) {
404	        return sheets.findById(id).orElseGet(() -> create(id));
405	    }
406	
407	    /**
408	     * The sheet's today. Every decision that depends on the date, and every default date, uses this
409	     * and never the real clock.
410	     */
411	    @Transactional
412	    public LocalDate today(String id) {
413	        return load(id).getToday();
414	    }
415	
416	    /** Change the sheet's today. */
417	    @Transactional
418	    public Sheet setToday(String id, LocalDate today) {
419	        Sheet sheet = load(id);
420	        sheet.setToday(today);
421	        return sheets.saveAndFlush(sheet);
422	    }
423	
424	    /**
425	     * The sheet's next claim number: 1 for its first opened claim, then 2, and so on. The sheet stays
426	     * locked until the transaction ends, so two claims opened at once never share a number.
427	     */
428	    @Transactional
429	    public int nextClaimNumber(String id) {
430	        load(id);
431	        sheets.takeClaimNumber(id);
432	        return sheets.claimNumbersUsed(id);
433	    }
434	
435	    private Sheet create(String id) {
436	        try {
437	            // The only use of the real clock: a new sheet's today starts as the real date.
438	            return sheets.saveAndFlush(new Sheet(id, Instant.now(), LocalDate.now()));
439	        } catch (DataIntegrityViolationException raced) {
440	            // Another user loaded the same new id at the same moment.
441	            return sheets.findById(id).orElseThrow(() -> raced);
442	        }
443	    }
444	}
