466	@Service
467	public class StatementService {
468	
469	    /** A person's statements: how many were taken, and the last one (none when none was). */
470	    public record Summary(long personId, int count, Statement last) {
471	    }
472	
473	    /** A statement just taken: the person's summary after it, and their claims as it bound them, newest first. */
474	    public record Taken(Summary summary, List<Claim> claims) {
475	    }
476	
477	    private final StatementRepository statements;
478	    private final PersonRepository people;
479	    private final ClaimRepository claims;
480	    private final ClaimService claimService;
481	    private final RateService rates;
482	    private final SheetService sheets;
483	    private final Audit audit;
484	
485	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
486	            ClaimService claimService, RateService rates, SheetService sheets, Audit audit) {
487	        this.statements = statements;
488	        this.people = people;
489	        this.claims = claims;
490	        this.claimService = claimService;
491	        this.rates = rates;
492	        this.sheets = sheets;
493	        this.audit = audit;
494	    }
495	
496	    /** The statement summary of each person on the sheet who has had a statement taken. */
497	    @Transactional(readOnly = true)
498	    public List<Summary> list(String sheetId) {
499	        Map<Long, Summary> by = new LinkedHashMap<>();
500	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
501	            Summary was = by.get(s.getPersonId());
502	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
503	        }
504	        return List.copyOf(by.values());
505	    }
506	
507	    /** Take the person's statement: record their due-total now, bind each of their counting claims to
508	     *  the figure it shows now, and leave every other claim of theirs unbound. */
509	    @Transactional
510	    public Taken take(String sheetId, String user, long personId) {
511	        Person person = people.findForUpdate(personId, sheetId)
512	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
513	        LocalDate today = sheets.today(sheetId);
514	        List<Claim> theirs = claims.findForStatement(sheetId, personId);
515	        BigDecimal total = BigDecimal.ZERO.setScale(2);
516	        boolean keptFigure = false;
517	        int counting = 0;
518	        for (Claim claim : theirs) {
519	            if (!counts(claim)) {
520	                claim.unbind();
521	                continue;
522	            }
523	            counting++;
524	            BigDecimal figure = claimService.figure(sheetId, person, claim);
525	            if (figure != null) total = total.add(figure);
526	            if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) keptFigure = true;
527	            claim.bind(figure);
528	        }
529	        // As the screen shows it: n/a when no rate of the grade is in force today and no claim keeps a figure.
530	        BigDecimal dueTotal = rates.inForce(sheetId, person.getGrade(), today) == null && !keptFigure ? null : total;
531	        claims.saveAllAndFlush(theirs);
532	        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, counting, today, user));
533	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
534	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counting);
535	        List<Statement> all = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
536	        return new Taken(new Summary(personId, all.size(), all.get(all.size() - 1)), theirs);
537	    }
538	
539	    /** Only open and settled claims count toward what is claimed and due. */
540	    private static boolean counts(Claim claim) {
541	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
542	    }
543	}
