package net.officefloor.hq.app.rate;


/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
 *  (or from the beginning of time, when it has none) until the grade's next rate. */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "grade", nullable = false)
    private Grade grade;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    protected Rate() {
    }

    public Rate(String sheetId, Grade grade, LocalDate from, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        setPct(pct);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Grade getGrade() {
        return grade;
    }

    /** The date the rate is in force from, or null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getPct() {
        return pct;
    }

    /** Change the percent; it is kept to two decimals. */
    public void setPct(BigDecimal pct) {
        this.pct = pct.setScale(2);
    }

    /** Whether the rate is in force on or before this date. */
    public boolean appliesBy(LocalDate date) {
        return from == null || !from.isAfter(date);
    }
}
package net.officefloor.hq.app.rate;


public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates in grade order, each grade's from the beginning of time first, then by from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId order by r.grade asc, r.from asc nulls first")
    List<Rate> findBySheetIdInOrder(@Param("sheetId") String sheetId);

    /** The grade's rates, with the one with no from-date first, then by from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade order by r.from asc nulls first")
    List<Rate> findForGrade(@Param("sheetId") String sheetId, @Param("grade") Grade grade);

    /** The grade's rate with no from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade and r.from is null")
    Optional<Rate> findFromStart(@Param("sheetId") String sheetId, @Param("grade") Grade grade);

    /** The grade's rate with this from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade and r.from = :from")
    Optional<Rate> findFrom(@Param("sheetId") String sheetId, @Param("grade") Grade grade,
            @Param("from") LocalDate from);
}
package net.officefloor.hq.app.claim;


public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The person's claims, locked until the transaction ends, so a statement binds them all at one moment. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
